export const DownloadBanner = ({ onHide, manualDownloadUrl }: IProps) => {
  const t = useFm();
  const { locale } = useRouter();
  const [isShow, setIsShow] = useState(true)
  const onClose = () => {
    setIsShow(false)
    onHide && onHide()
  }
  const onDownLoad = () => {
    window.location.pathname = manualDownloadUrl || `${locale}/downloadApp/`
  }
  if (!isShow) return;
  return (
    <div className="fixed bottom-0 w-full h-20 bg-bg-secondary z-50 md:hidden">
      <div className="absolute w-full h-full flex justify-between items-center pl-2 pr-2 gap-4" >
        <div className=" flex-1 flex justify-start items-center gap-2">
          <div className='w-12 h-12 flex justify-end items-center'>
            <LogoIcon />
          </div>

          <div>
            <h1 className="text-[16px] font-bold text-text-white"> EasiCoin </h1>
            <p className="text-[12px] text-text-white">{t('bannerTitle2')}</p>
          </div>
        </div>

        <div className='w-[121px] flex items-center justify-between'>
          <div className='w-[93px] h-[32px] text-sm font-semibold bg-fill-button-brand-default rounded-[12px]
                flex justify-center items-center text-text-black' onClick={onDownLoad}>{t('download')}</div>
          <div onClick={onClose} className='w-5 h-5 flex justify-center items-center'><CloseIcon /></div>
        </div>
      </div>
      {/* <BannerBg /> */}
    </div >
  )
}

